// The arrow is the phase: out, back, or failed.
func phaseArrow(phase *domain.CallPhase) string {
	if phase == nil {
		return "·"
	}
	switch *phase {
	case domain.CallPhaseRequest:
		return "→"
	case domain.CallPhaseResponse:
		return "←"
	case domain.CallPhaseError:
		return "✕"
	default:
		return "·"
	}
}

func methodColor(method *string) string {
	if method == nil {
		return "text-cs-muted"
	}
	switch strings.ToUpper(*method) {
	case "GET":
		return "text-[#3FB950]"
	case "POST", "PUT", "PATCH":
		return "text-[#D29922]"
	case "DELETE":
		return "text-[#F85149]"
	default:
		return "text-cs-muted"
	}
}

// urlPath trims the host so a list of calls to one API lines up on the part
// that differs. The full URL stays in the expanded detail.
func urlPath(raw string) string {
	if u, err := url.Parse(raw); err == nil && u.Host != "" {
		if u.Path == "" {
			return "/"
		}
		if u.RawQuery != "" {
			return u.Path + "?" + u.RawQuery
		}
		return u.Path
	}
	return raw
}

func statusColor(code int) string {
	switch {
	case code >= 500:
		return "bg-[rgba(255,77,106,0.15)] text-[#FF4D6A]"
	case code >= 400:
		return "bg-[rgba(248,81,73,0.15)] text-[#F85149]"
	case code >= 300:
		return "bg-[rgba(210,153,34,0.15)] text-[#D29922]"
	default:
		return "bg-[rgba(63,185,80,0.15)] text-[#3FB950]"
	}
}

func levelBorderColor(level string) string {
	switch level {
	case "fatal":
		return "border-l-[#FF4D6A]"
	case "error":
		return "border-l-[#F85149]"
	case "warning":
		return "border-l-[#D29922]"
	case "info":
		return "border-l-[#0084FF]"
	case "debug":
		return "border-l-[#3FB950]"
	case "system":
		return "border-l-[#A371F7]"
	default:
		return "border-l-cs-border"
	}
}

func prettyJSON(raw json.RawMessage) string {
	var obj interface{}
	if err := decodeJSON(raw, &obj); err != nil {
		return string(raw)
	}
	pretty, err := json.MarshalIndent(obj, "", "  ")
	if err != nil {
		return string(raw)
	}
	return string(pretty)
}

// parseTags unmarshals the stored JSON tag array; nil on error or empty.
func parseTags(raw json.RawMessage) []string {
	var tags []string
	if err := json.Unmarshal(raw, &tags); err != nil {
		return nil
	}
	return tags
}

// hasJSONContent reports whether raw holds anything beyond {} / [] / null.
func hasJSONContent(raw *json.RawMessage) bool {
	if raw == nil {
		return false
	}
	switch string(*raw) {
	case "", "{}", "[]", "null":
		return false
	}
	return true
}

